"""
Node "Code in Python" - n8n
Etape RAW -> CLEAN du pipeline "Qualite de l'air" (workflow DONNEE2)

A coller tel quel dans le node "Code in Python", en mode "Run Once for All Items".

CORRECTIFS (v3) par rapport aux versions precedentes :
1. Timestamp reconstruit par interpolation (period.start/end/nb_points) quand
   aucun "dt"/"timestamp"/"time" explicite n'est fourni par l'entree.
2. Detection automatique du mode d'input runner : "_items" (Pyodide) ou
   "_input.all()" (runner natif), sans intervention manuelle.
3. NOUVEAU : gere le cas ou un node "Aggregate" en amont a regroupe plusieurs
   villes dans UN SEUL item n8n, sous la forme {"data": [ville1, ville2, ...]}.
   Avant ce correctif, le script traitait ce tableau de villes comme un
   tableau de MESURES d'une seule ville -> aucune ligne ne matchait "aqi"/
   composants -> sortie vide ("No output data returned").
   Le script detecte maintenant automatiquement si "data" contient des objets
   "ville" (avec "period"/"coord"/"lat") ou des objets "mesure" (avec "main"/
   "components"), et s'adapte sans configuration supplementaire.

Output : une liste d'items n8n ([{"json": {...}}, ...]) prete pour "Convert to File".
"""

from datetime import datetime, timedelta, timezone

# ----------------------------------------------------------------------
# 1. Table de correspondance lat/lon -> ville
# ----------------------------------------------------------------------
CITY_LOOKUP = {
    (-18.9185, 47.5211): "Antananarivo",
    (-23.3583, 43.6672): "Toliara",
    (-18.1716, 49.3761): "Toamasina",
    (-15.7180, 46.3173): "Mahajanga",
    (-12.2783, 49.2915): "Antsiranana",
}

POLLUTANT_COLUMNS = ["co", "no", "no2", "o3", "so2", "pm2_5", "pm10", "nh3"]
REQUIRED_OUTPUT_COLUMNS = [
    "city", "lat", "lon", "dt", "datetime_utc", "aqi",
    "co", "no", "no2", "o3", "so2", "pm2_5", "pm10", "nh3",
    "has_missing_pollutant", "dt_interpolated",
]


def resolve_city(lat, lon):
    if lat is None or lon is None:
        return None
    try:
        lat_f, lon_f = float(lat), float(lon)
    except (TypeError, ValueError):
        return None

    key = (round(lat_f, 4), round(lon_f, 4))
    if key in CITY_LOOKUP:
        return CITY_LOOKUP[key]

    key2 = (round(lat_f, 2), round(lon_f, 2))
    for (k_lat, k_lon), name in CITY_LOOKUP.items():
        if round(k_lat, 2) == key2[0] and round(k_lon, 2) == key2[1]:
            return name

    return f"Inconnue ({lat},{lon})"


def to_number(x):
    if x is None:
        return None
    try:
        return float(x)
    except (TypeError, ValueError):
        return None


def to_iso(dt):
    if dt is None:
        return None
    try:
        return datetime.fromtimestamp(float(dt), tz=timezone.utc).isoformat()
    except (TypeError, ValueError, OSError, OverflowError):
        return None


def parse_iso(s):
    if not s or not isinstance(s, str):
        return None
    try:
        return datetime.fromisoformat(s)
    except ValueError:
        return None


def interpolate_timestamp(start, end, index, total):
    if start is None:
        return None
    if end is None or total <= 1:
        return int(start.timestamp())
    step_seconds = (end - start).total_seconds() / (total - 1)
    return int((start + timedelta(seconds=step_seconds * index)).timestamp())


# ----------------------------------------------------------------------
# 2. Aplatissement d'un item "1 ville" en mesures
# ----------------------------------------------------------------------
def flatten_record(raw):
    if not isinstance(raw, dict):
        return []

    coord = raw.get("coord") or {}
    lat = coord.get("lat", raw.get("lat"))
    lon = coord.get("lon", raw.get("lon"))
    measurements = raw.get("list") or raw.get("data") or []
    city = resolve_city(lat, lon)

    period = raw.get("period") or {}
    period_start = parse_iso(period.get("start"))
    period_end = parse_iso(period.get("end"))
    total = len(measurements)

    rows = []
    for i, entry in enumerate(measurements):
        if not isinstance(entry, dict):
            continue
        components = entry.get("components") or {}

        dt = entry.get("dt") or entry.get("timestamp") or entry.get("time")
        dt_interpolated = False
        if dt is None:
            dt = interpolate_timestamp(period_start, period_end, i, total)
            dt_interpolated = dt is not None

        rows.append({
            "city": city,
            "lat": to_number(lat),
            "lon": to_number(lon),
            "dt": dt,
            "aqi": to_number((entry.get("main") or {}).get("aqi")),
            "co": to_number(components.get("co")),
            "no": to_number(components.get("no")),
            "no2": to_number(components.get("no2")),
            "o3": to_number(components.get("o3")),
            "so2": to_number(components.get("so2")),
            "pm2_5": to_number(components.get("pm2_5")),
            "pm10": to_number(components.get("pm10")),
            "nh3": to_number(components.get("nh3")),
            "dt_interpolated": dt_interpolated,
        })
    return rows


def is_city_record(d):
    """Objet qui represente UNE ville (a la racine ou dans un tableau agrege)."""
    if not isinstance(d, dict):
        return False
    return ("period" in d) or ("coord" in d) or ("lat" in d and "data" in d) or ("lat" in d and "list" in d)


def expand_top_level(top):
    """
    Gere le cas ou un node "Aggregate" en amont a regroupe plusieurs villes
    dans un seul item sous la forme {"data": [ville1, ville2, ...]}.
    Retourne toujours une liste d'objets "1 ville" a passer a flatten_record.
    """
    if not isinstance(top, dict):
        return []

    data_field = top.get("data")
    if isinstance(data_field, list) and data_field and is_city_record(data_field[0]):
        # "data" contient des objets ville (cas Aggregate) -> on les deplie
        return [d for d in data_field if isinstance(d, dict)]

    # Sinon, "top" est deja directement un objet ville
    return [top]


# ----------------------------------------------------------------------
# 3. Nettoyage
# ----------------------------------------------------------------------
def clean_rows(rows):
    rows = [
        r for r in rows
        if r.get("aqi") is not None or any(r.get(c) is not None for c in POLLUTANT_COLUMNS)
    ]

    rows = [r for r in rows if r.get("dt") is not None]
    for r in rows:
        r["dt"] = int(r["dt"])
        r["datetime_utc"] = to_iso(r["dt"])

    seen = set()
    deduped = []
    for r in rows:
        key = (r.get("city"), r.get("dt"))
        if key not in seen:
            seen.add(key)
            deduped.append(r)
    rows = deduped

    for r in rows:
        r["has_missing_pollutant"] = any(r.get(c) is None for c in POLLUTANT_COLUMNS)

    rows.sort(key=lambda r: (r.get("city") or "", r.get("dt") or 0))

    return [{col: r.get(col) for col in REQUIRED_OUTPUT_COLUMNS} for r in rows]


# ----------------------------------------------------------------------
# 4. Point d'entree n8n
# ----------------------------------------------------------------------
try:
    source_items = _items  # ancien runner Pyodide
except NameError:
    source_items = _input.all()  # runner natif

all_rows = []
for item in source_items:
    top = item["json"] if isinstance(item, dict) else item.json
    for raw in expand_top_level(top):
        all_rows.extend(flatten_record(raw))

clean = clean_rows(all_rows)

return [{"json": row} for row in clean]
